Data Loading & Preparation
We load the county election returns and calculate two-party vote shares, vote counts, and victory margins.


Code
county_data &lt;- read_csv("data/20221108__fl__general__county.csv")

# Filter for Governor race and compute margins by county
gov_results &lt;- county_data |&gt;
  filter(office == "Governor", party %in% c("DEM", "REP")) |&gt;
  group_by(county, party) |&gt;
  summarize(votes = sum(votes), .groups = "drop") |&gt;
  pivot_wider(names_from = party, values_from = votes) |&gt;
  mutate(
    total_votes = DEM + REP,
    rep_pct = REP / total_votes * 100,
    dem_pct = DEM / total_votes * 100,
    rep_margin = (REP - DEM) / total_votes * 100,
    winner = if_else(rep_margin &gt; 0, "DeSantis (REP)", "Crist (DEM)"),
    county_clean = str_remove_all(tolower(county), "[. ]")
  )
